// Generated by AutoDeploy. Signs Android release builds with the upload key named by
// ANDROID_KEYSTORE_FILE / ANDROID_KEYSTORE_PASSWORD / ANDROID_KEY_ALIAS / ANDROID_KEY_PASSWORD.
// Without them the release build is signed with the debug key (fine for testing, not for Google Play).
const { withAppBuildGradle } = require('expo/config-plugins')

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents
    if (gradle.includes('autodeployRelease')) return cfg
    gradle = gradle.replace(/signingConfigs\s*\{/, `signingConfigs {
        autodeployRelease {
            if (System.getenv('ANDROID_KEYSTORE_FILE')) {
                storeFile file(System.getenv('ANDROID_KEYSTORE_FILE'))
                storePassword System.getenv('ANDROID_KEYSTORE_PASSWORD')
                keyAlias System.getenv('ANDROID_KEY_ALIAS') ?: 'upload'
                keyPassword System.getenv('ANDROID_KEY_PASSWORD') ?: System.getenv('ANDROID_KEYSTORE_PASSWORD')
            }
        }`)
    gradle = gradle.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/,
      "$1signingConfig System.getenv('ANDROID_KEYSTORE_FILE') ? signingConfigs.autodeployRelease : signingConfigs.debug"
    )
    cfg.modResults.contents = gradle
    return cfg
  })
}
